"""Runtime value semantics for minisql.

This module owns the meaning of values at execution time: CSV field
coercion, three-valued truth, arithmetic, comparison, ``LIKE``, scalar
functions and aggregates.  Everything here is a pure function of its
arguments; the parser and executor import this module, never the other way
around.

Values are ``int``, ``float``, ``str``, ``bool`` or ``None`` (SQL NULL).
Booleans are deliberately *not* treated as numbers, even though Python's
``bool`` is a subclass of ``int``.
"""

from __future__ import annotations

import re
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP, localcontext
from typing import Any, List, Optional, Sequence, Union

from .errors import QueryError

Value = Union[int, float, str, bool, None]

_INT_RE = re.compile(r"-?[0-9]+\Z")
_FLOAT_RE = re.compile(r"(?:-?[0-9]+\.[0-9]*|-?[0-9]*\.[0-9]+)\Z")

_ARITH_OPS = ("+", "-", "*", "/")
_COMPARE_OPS = ("=", "!=", "<", "<=", ">", ">=")


# ---------------------------------------------------------------------------
# Small type helpers
# ---------------------------------------------------------------------------


def _is_number(value: Any) -> bool:
    """Return whether *value* is a number for SQL purposes (not a bool)."""
    return isinstance(value, (int, float)) and not isinstance(value, bool)


def _type_name(value: Any) -> str:
    """A user-facing name for a value's type, used in error messages."""
    if isinstance(value, bool):
        return "boolean"
    if isinstance(value, int):
        return "integer"
    if isinstance(value, float):
        return "float"
    if isinstance(value, str):
        return "string"
    return type(value).__name__


def _kind(value: Any) -> Optional[str]:
    """Comparison family of *value*, or ``None`` for unsupported values."""
    if isinstance(value, bool):
        return "boolean"
    if _is_number(value):
        return "number"
    if isinstance(value, str):
        return "string"
    return None


def _require_number(value: Any, context: str) -> None:
    if not _is_number(value):
        raise QueryError(
            "%s expects a number, got %s" % (context, _type_name(value))
        )


def _require_string(value: Any, context: str) -> None:
    if not isinstance(value, str):
        raise QueryError(
            "%s expects a string, got %s" % (context, _type_name(value))
        )


# ---------------------------------------------------------------------------
# CSV cells and text
# ---------------------------------------------------------------------------


def coerce_cell(text: str) -> Value:
    """Convert one CSV field to an SQL value.

    Empty text is NULL; an integer-looking field becomes ``int``; a
    decimal-looking field becomes ``float``; anything else is returned
    unchanged (not stripped).
    """
    if text == "":
        return None
    if _INT_RE.fullmatch(text):
        return int(text)
    if _FLOAT_RE.fullmatch(text):
        return float(text)
    return text


def to_text(value: Any) -> str:
    """Text representation used by ``||``.

    Strings are unchanged; every other non-NULL value uses ``str()``.
    """
    if isinstance(value, str):
        return value
    return str(value)


def concat(left: Any, right: Any) -> Optional[str]:
    """SQL ``||``: NULL when either side is NULL, else the joined text."""
    if left is None or right is None:
        return None
    return to_text(left) + to_text(right)


# ---------------------------------------------------------------------------
# Three-valued truth
# ---------------------------------------------------------------------------


def truth(value: Any) -> Optional[bool]:
    """Coerce a condition value to three-valued truth.

    ``None`` stays ``None`` and booleans pass through; every other type is
    an error (numbers and strings are not SQL truth values).
    """
    if value is None:
        return None
    if isinstance(value, bool):
        return value
    raise QueryError(
        "expected a boolean condition, got %s" % _type_name(value)
    )


# ---------------------------------------------------------------------------
# Arithmetic
# ---------------------------------------------------------------------------


def arith(op: str, left: Any, right: Any) -> Value:
    """Apply a binary arithmetic operator.

    NULL operands give NULL.  ``/`` is true division, always yields a
    float and yields NULL for a zero divisor.  ``+``, ``-`` and ``*`` keep
    exact integer arithmetic when both operands are integers and otherwise
    produce a float.  Booleans and strings are errors.
    """
    if op not in _ARITH_OPS:
        raise QueryError("unknown arithmetic operator %r" % (op,))
    if left is None or right is None:
        return None
    _require_number(left, "operator %r" % op)
    _require_number(right, "operator %r" % op)

    if op == "/":
        if right == 0:
            return None
        return left / right

    if isinstance(left, int) and isinstance(right, int):
        if op == "+":
            return left + right
        if op == "-":
            return left - right
        return left * right

    left = float(left)
    right = float(right)
    if op == "+":
        return left + right
    if op == "-":
        return left - right
    return left * right


# ---------------------------------------------------------------------------
# Comparison
# ---------------------------------------------------------------------------


def _compare_checked(op: str, left: Any, right: Any) -> Value:
    """Common validation for :func:`compare` and :func:`compare_values`."""
    left_kind = _kind(left)
    right_kind = _kind(right)
    if left_kind is None:
        raise QueryError("cannot compare value of type %s" % _type_name(left))
    if right_kind is None:
        raise QueryError("cannot compare value of type %s" % _type_name(right))
    if left_kind != right_kind:
        raise QueryError(
            "cannot compare %s with %s"
            % (_type_name(left), _type_name(right))
        )
    return left_kind


def compare(op: str, left: Any, right: Any) -> Optional[bool]:
    """Apply a SQL comparison operator, with three-valued NULL semantics."""
    if op not in _COMPARE_OPS:
        raise QueryError("unknown comparison operator %r" % (op,))
    if left is None or right is None:
        return None
    _compare_checked(op, left, right)

    if op == "=":
        return left == right
    if op == "!=":
        return left != right
    if op == "<":
        return left < right
    if op == "<=":
        return left <= right
    if op == ">":
        return left > right
    return left >= right


def compare_values(left: Any, right: Any) -> int:
    """Total ordering for two non-NULL values.

    Returns ``-1``, ``0`` or ``1``.  Both arguments must be from the same
    comparison family (numbers, strings, or booleans).
    """
    _compare_checked("order", left, right)
    if left < right:
        return -1
    if left > right:
        return 1
    return 0


# ---------------------------------------------------------------------------
# LIKE
# ---------------------------------------------------------------------------


def like(value: Any, pattern: Any) -> Optional[bool]:
    """SQL ``LIKE``: whole-string, case-sensitive wildcard match.

    ``%`` matches any run of characters (including none) and ``_`` matches
    exactly one character.  There is no escape character.  NULL operands
    give NULL; non-string operands are errors.
    """
    if value is None or pattern is None:
        return None
    if not isinstance(value, str):
        raise QueryError("LIKE expects a string, got %s" % _type_name(value))
    if not isinstance(pattern, str):
        raise QueryError(
            "LIKE expects a string pattern, got %s" % _type_name(pattern)
        )

    # Dynamic programming over prefixes.  prev[j] means "pattern prefix
    # processed so far matches the first j characters of value".
    prev = [False] * (len(value) + 1)
    prev[0] = True
    for char in pattern:
        cur = [False] * (len(value) + 1)
        if char == "%":
            # Either consume no text (prev[j]) or extend a run (cur[j-1]).
            cur[0] = prev[0]
            for j in range(1, len(value) + 1):
                cur[j] = prev[j] or cur[j - 1]
        elif char == "_":
            for j in range(1, len(value) + 1):
                cur[j] = prev[j - 1]
        else:
            for j in range(1, len(value) + 1):
                cur[j] = prev[j - 1] and value[j - 1] == char
        prev = cur
    return prev[len(value)]


# ---------------------------------------------------------------------------
# Decimal rounding helper
# ---------------------------------------------------------------------------


def _round_to(value: Any, places: int) -> Decimal:
    """Round *value* to *places* decimal places, halves away from zero."""
    _require_number(value, "ROUND()")
    try:
        decimal_value = Decimal(str(value))
        exponent = Decimal(1).scaleb(-places)
        with localcontext() as context:
            # Make sure quantize can represent every digit it may need.
            context.prec = max(28, decimal_value.adjusted() + 1 + abs(places) + 2)
            return decimal_value.quantize(exponent, rounding=ROUND_HALF_UP)
    except (InvalidOperation, ValueError, OverflowError):
        raise QueryError("ROUND() value is out of range")


# ---------------------------------------------------------------------------
# Scalar functions
# ---------------------------------------------------------------------------


def call(name: str, args: List[Any]) -> Value:
    """Dispatch a scalar function call.

    *name* is expected to be lowercase and *args* are already evaluated.
    NULL propagates for every function except ``COALESCE``.  Unknown
    functions and wrong arities are query errors.
    """
    name = name.lower()

    if name == "coalesce":
        if len(args) < 1:
            raise QueryError("COALESCE() requires at least one argument")
        for arg in args:
            if arg is not None:
                return arg
        return None

    fixed_arity = {
        "lower": 1,
        "upper": 1,
        "length": 1,
        "abs": 1,
    }
    if name == "round":
        if len(args) not in (1, 2):
            raise QueryError(
                "ROUND() expects 1 or 2 arguments, got %d" % len(args)
            )
    elif name in fixed_arity:
        expected = fixed_arity[name]
        if len(args) != expected:
            raise QueryError(
                "%s() expects %d argument%s, got %d"
                % (name.upper(), expected, "" if expected == 1 else "s", len(args))
            )
    else:
        raise QueryError("unknown function %r" % (name,))

    # NULL propagation takes precedence over operand type checks.
    if any(arg is None for arg in args):
        return None

    if name == "lower":
        _require_string(args[0], "LOWER()")
        return args[0].lower()
    if name == "upper":
        _require_string(args[0], "UPPER()")
        return args[0].upper()
    if name == "length":
        _require_string(args[0], "LENGTH()")
        return len(args[0])
    if name == "abs":
        _require_number(args[0], "ABS()")
        return abs(args[0])

    # ROUND
    if len(args) == 1:
        return int(_round_to(args[0], 0))

    places = args[1]
    if not isinstance(places, int) or isinstance(places, bool):
        raise QueryError(
            "ROUND() expects an integer number of decimal places, got %s"
            % _type_name(places)
        )
    return float(_round_to(args[0], places))


# ---------------------------------------------------------------------------
# Aggregates
# ---------------------------------------------------------------------------


def aggregate(name: str, values: Sequence[Any], star: bool = False) -> Value:
    """Compute an aggregate over per-row argument values.

    ``values`` may contain NULLs (which are ignored by everything except
    ``COUNT(*)``).  For ``COUNT(*)`` the executor passes ``star=True`` and
    ``values`` is simply one marker per row.
    """
    name = name.lower()
    known = ("count", "sum", "avg", "min", "max")
    if name not in known:
        raise QueryError("unknown aggregate %r" % (name,))
    if star and name != "count":
        raise QueryError("%s(*) is not a valid aggregate" % name.upper())

    if name == "count":
        if star:
            return len(values)
        return sum(1 for value in values if value is not None)

    non_null = [value for value in values if value is not None]
    if not non_null:
        return None

    if name == "sum":
        has_float = False
        for value in non_null:
            _require_number(value, "SUM()")
            if isinstance(value, float):
                has_float = True
        total = sum(non_null)
        return float(total) if has_float else total

    if name == "avg":
        for value in non_null:
            _require_number(value, "AVG()")
        return float(sum(non_null)) / len(non_null)

    # MIN / MAX keep the original value and use the total value ordering.
    best = non_null[0]
    for value in non_null[1:]:
        order = compare_values(value, best)
        if (name == "min" and order < 0) or (name == "max" and order > 0):
            best = value
    return best

