# Randomized LIKE cross-check against an independent recursive matcher.
import itertools
import random

def ref_like(text, pat):
    if not pat:
        return text == ""
    head, rest = pat[0], pat[1:]
    if head == "%":
        return any(ref_like(text[i:], rest) for i in range(len(text) + 1))
    if head == "_":
        return bool(text) and ref_like(text[1:], rest)
    return bool(text) and text[0] == head and ref_like(text[1:], rest)

